"Object.defineProperty(window, '__doorstepNativeLocation', {
  value: { version: 1, platform: 'ios', heading: true }, writable: false, configurable: false
});"

"(() => {
  if (window.dsgo && typeof window.dsgo.recenter === 'function') {
    window.dsgo.recenter()
    return 'api'
  }

  const clickableAncestor = (node) => node?.closest(
    'button, [role="button"], [data-dsgo-control="recenter"], [class*="cursor-pointer"]'
  )

  let control = document.querySelector('[data-dsgo-control="recenter"]')
    || document.querySelector('[aria-label="recenter map" i]')
    || clickableAncestor(document.querySelector('svg.lucide-focus'))

  if (!control) {
    const standardGlyph = Array.from(document.querySelectorAll('svg[viewBox="0 0 24 24"]'))
      .find((svg) => {
        const paths = Array.from(svg.querySelectorAll('path'))
        const pathData = paths.map((path) => path.getAttribute('d') || '')
        return paths.length === 5
          && pathData.some((d) => d.startsWith('M12 3'))
          && pathData.some((d) => d.startsWith('M3.00781 12'))
          && pathData.some((d) => d.startsWith('M19.0156 12'))
      })
    control = clickableAncestor(standardGlyph)
  }

  // Deployed Doorstep Go versions have shipped more than one focus glyph.
  // The control's layout contract is steadier than its SVG: it is the only
  // clickable, fixed, circular SVG control anchored to the viewport bottom.
  if (!control) {
    control = Array.from(document.querySelectorAll('[class*="cursor-pointer"]'))
      .find((element) => {
        const style = getComputedStyle(element)
        return style.position === 'fixed'
          && element.style.bottom !== ''
          && style.borderRadius !== '0px'
          && style.pointerEvents !== 'none'
          && element.querySelector('svg')
      })
  }

  if (!control) {
    const dropoffGlyph = Array.from(document.querySelectorAll('svg[viewBox="0 0 50 50"]'))
      .find((svg) => svg.querySelectorAll('circle').length === 2
        && svg.querySelectorAll('path').length >= 4)
    control = clickableAncestor(dropoffGlyph)
  }

  if (!control || typeof control.click !== 'function') return 'missing'
  control.click()
  return 'control'
})()"

"(function () {
  const read = () => {
    const s = getComputedStyle(document.documentElement)
    return {
      bg:     s.getPropertyValue('--th-button-bg').trim(),
      border: s.getPropertyValue('--th-button-border').trim(),
      icon:   s.getPropertyValue('--th-icon').trim(),
      sv:     document.documentElement.dataset.sv || 'closed',
    }
  }
  let last = ''
  const post = () => {
    const t = read()
    if (!t.bg) return
    const key = [t.bg, t.border, t.icon, t.sv].join('|')
    if (key === last) return
    last = key
    window.webkit?.messageHandlers?.dsgoState?.postMessage(t)
  }
  new MutationObserver(post).observe(document.documentElement, {
    attributes: true, attributeFilter: ['style', 'data-sv'],
  })
  let n = 0
  const id = setInterval(() => { post(); if (++n > 40) clearInterval(id) }, 100)
  post()
})()"
